cd /workspace && python3 - <<'PY'
import subprocess, sys, os
try:
    p = subprocess.Popen([sys.executable, '-c', 'print("hi")'], stdout=subprocess.PIPE, start_new_session=True)
    print('setsid popen ok:', p.communicate()[0])
except Exception as e: print('setsid popen FAIL', type(e).__name__, e)
try:
    p = subprocess.Popen([sys.executable, '-c', 'print("hi")'], stdout=subprocess.PIPE)
    print('plain popen ok:', p.communicate()[0])
except Exception as e: print('plain popen FAIL', type(e).__name__, e)
try:
    os.setsid(); print('setsid direct ok')
except Exception as e: print('setsid direct FAIL', e)
PY
